                'seo_title' => trim((string)$d['seo_title']), 'meta_desc' => trim((string)$d['meta_desc']), 'weight_kg' => is_numeric($d['weight_kg'] ?? null) && (float)$d['weight_kg'] > 0 ? round((float)$d['weight_kg'], 3) : null,
                'sort_number' => preg_match('/[A-Za-z]*0*(\d+)/', (string)$d['card_number'], $m) ? (float)$m[1] : null];
            if ($img !== $p['image_url']) $vals['image_local'] = '';
            // a description edited by hand is kept; an untouched automatic one stays automatic (and is rewritten if card details change)
            $norm = fn($x) => trim(preg_replace('/\s+/u', ' ', html_entity_decode(strip_tags((string)$x), ENT_QUOTES)));
            $vals['desc_auto'] = $norm($vals['description']) === '' ? 1 : (($id && $norm($vals['description']) !== $norm($p['description'] ?? '')) ? 0 : (int)($p['desc_auto'] ?? 1));
