function editor(string $name, string $html, int $rows = 18): string {
    return '<div class="editor" data-editor><div class="toolbar"><button type="button" data-cmd="formatBlock" data-val="h2">H2</button><button type="button" data-cmd="formatBlock" data-val="h3">H3</button><button type="button" data-cmd="bold"><b>B</b></button><button type="button" data-cmd="italic"><i>I</i></button><button type="button" data-cmd="insertUnorderedList">â€¢ List</button><button type="button" data-cmd="insertOrderedList">1. List</button><button type="button" data-cmd="createLink">Link</button><button type="button" data-cmd="formatBlock" data-val="blockquote">Quote</button><button type="button" data-cmd="formatBlock" data-val="p">Â¶</button><label class="tb-file">Image<input type="file" accept="image/jpeg,image/png,image/webp" data-editor-image hidden></label><button type="button" data-source>HTML</button></div>'
        . '<div class="area" contenteditable="true" style="min-height:' . ($rows * 22) . 'px">' . sanitize_html($html) . '</div><textarea name="' . h($name) . '" hidden>' . h($html) . '</textarea></div>';
}
function admin_page_edit(): void {
    $path = (string)($_GET['path'] ?? '');
    $pg = $path !== '' ? one('SELECT * FROM pages WHERE path = ?', [$path]) : null;
    $type = $pg['type'] ?? (in_array($_GET['type'] ?? '', ['guide', 'blog', 'page'], true) ? $_GET['type'] : 'blog');
    $pg = $pg ?: ['path' => '', 'type' => $type, 'title' => '', 'h1' => '', 'excerpt' => '', 'body' => '', 'seo_title' => '', 'meta_desc' => '', 'primary_kw' => '', 'image' => '', 'published' => 0, 'seo_index' => 1];
    $err = '';
    if (is_post()) {
        if (!empty($_POST['delete']) && $path !== '') { q('DELETE FROM pages WHERE path = ?', [$path]); flash('Page deleted.'); redirect('/admin/pages'); }
        $title = trim((string)$_POST['title']);
        $prefix = ['guide' => '/guides/', 'blog' => '/blog/', 'page' => '/'][$type];
        $slug = slugify(trim((string)($_POST['slug'] ?? '')) ?: $title);
        $newPath = $path !== '' && trim((string)($_POST['slug'] ?? '')) === '' ? $path : $prefix . $slug;
        if ($title === '') $err = 'Give the page a title.';
        elseif ($newPath !== $path && (one('SELECT 1 FROM pages WHERE path = ?', [$newPath]) || one('SELECT 1 FROM collections WHERE path = ?', [$newPath]))) $err = 'Another page already uses that web address.';
        if (!$err) {
            $vals = [$newPath, $type, $title, trim((string)$_POST['h1']) ?: $title, trim((string)$_POST['excerpt']), sanitize_html((string)$_POST['body']), trim((string)$_POST['seo_title']), trim((string)$_POST['meta_desc']),
                     trim((string)$_POST['primary_kw']), trim((string)$_POST['image']), isset($_POST['published']) ? 1 : 0, isset($_POST['seo_index']) ? 1 : 0];
            if ($path === '') q("INSERT INTO pages(path, type, title, h1, excerpt, body, seo_title, meta_desc, primary_kw, image, published, seo_index) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)", $vals);
            else {
                q("UPDATE pages SET path=?, type=?, title=?, h1=?, excerpt=?, body=?, seo_title=?, meta_desc=?, primary_kw=?, image=?, published=?, seo_index=?, updated_at=datetime('now'),
                   published_at = CASE WHEN published = 0 AND ? = 1 THEN datetime('now') ELSE published_at END WHERE path = ?", [...$vals, $vals[10], $path]);
                if ($newPath !== $path) q('INSERT OR REPLACE INTO redirects(from_path, to_path, code) VALUES(?, ?, 301)', [$path, $newPath]);
            }
            flash('Saved.' . ($newPath !== $path && $path !== '' ? ' The old address now redirects to the new one.' : ''));
            redirect('/admin/pages/edit?path=' . urlencode($newPath));
        }
        $pg = array_merge($pg, $_POST);
    }
    $slug = $pg['path'] !== '' ? basename($pg['path']) : '';
    ob_start(); ?>
<div class="head"><h1><?= $path ? 'Edit' : 'New' ?> <?= h(['guide' => 'guide', 'blog' => 'blog post', 'page' => 'page'][$type]) ?></h1><?php if ($path && $pg['published']): ?><a class="btn ghost" href="<?= h($path) ?>" target="_blank" rel="noopener">View on site â†—</a><?php endif ?></div>
<?php if ($err): ?><p class="alert"><?= h($err) ?></p><?php endif ?>
<form method="post" class="edit-grid"><?= csrf_field() ?>
  <div>
    <section class="card">
      <label>Title<input name="title" value="<?= h($pg['title']) ?>" required data-serp-source></label>
      <label>Heading on the page (H1) <span class="muted">blank = same as title</span><input name="h1" value="<?= h($pg['h1']) ?>"></label>
      <label>Short summary <span class="muted">(shown on the guides/blog list)</span><textarea name="excerpt" rows="2"><?= h($pg['excerpt']) ?></textarea></label>
      <?= editor('body', (string)$pg['body']) ?>
      <p class="muted small">Tips that help ranking: answer the main question in the first two sentences, use H2 headings phrased as questions people search, and link to at least three product or set pages.</p>
    </section>
  </div>
  <div>
    <section class="card"><h2>Publish</h2>
