  <div class="checks"><label class="inline"><input type="checkbox" name="published" <?= $r['published'] ? 'checked' : '' ?>> Show on the site</label><label class="inline"><input type="checkbox" name="featured" <?= $r['featured'] ? 'checked' : '' ?>> Show on the homepage</label></div>
