        <div class="table-wrap"><table class="rows">
          <thead><tr><th class="sr">Image</th><th>Product</th><th>Price per unit</th><th>Stock</th><th>Quantity</th></tr></thead>
          <tbody><?php foreach ($items as $p) view__row(['p' => $p]); ?></tbody>
        </table></div>
      <?php else: ?>
        <div class="grid"><?php foreach ($items as $p) view__card(['p' => $p]); ?></div>
      <?php endif ?>

      <?php if ($pages > 1): ?>
      <nav class="pager" aria-label="Pages">
        <?php if ($page > 1): ?><a href="<?= h(listing_url($base, $params + ['view' => null], ['page' => $page - 1])) ?>" rel="prev">â† Previous</a><?php endif ?>
        <?php $from = max(1, $page - 2); $to = min($pages, $page + 2);
        if ($from > 1) echo '<a href="' . h(listing_url($base, $params, ['page' => 1])) . '">1</a>' . ($from > 2 ? '<span>â€¦</span>' : '');
        for ($i = $from; $i <= $to; $i++) echo $i === $page ? "<span aria-current=\"page\">$i</span>" : '<a href="' . h(listing_url($base, $params, ['page' => $i])) . "\">$i</a>";
        if ($to < $pages) echo ($to < $pages - 1 ? '<span>â€¦</span>' : '') . '<a href="' . h(listing_url($base, $params, ['page' => $pages])) . "\">$pages</a>"; ?>
        <?php if ($page < $pages): ?><a href="<?= h(listing_url($base, $params, ['page' => $page + 1])) ?>" rel="next">Next â†’</a><?php endif ?>
      </nav>
      <?php endif ?>
    </section>
  </div>
  <?php if (!empty($cardlist)): $setLabel = $c['title']; $multiLang = count(array_unique(array_column($cardlist, 'language'))) > 1; ?>
  <section class="section cardlist" id="card-list" aria-labelledby="cl-h">
    <div class="sec-head"><h2 class="h2" id="cl-h"><?= h($setLabel) ?>: every card and price</h2><span class="mono small muted"><?= number_format(count($cardlist)) ?> cards</span></div>
    <p class="muted small">Every <?= h($setLabel) ?> single in our shop, ordered by card number with todayâ€™s price in <?= h(currency()) ?>. Reverse holos, pattern versions and promos are listed on their own lines.</p>
