    });
    const DOT = canvasTex(64, 64, g => { const r = g.createRadialGradient(32, 32, 0, 32, 32, 32); r.addColorStop(0, 'rgba(255,240,200,1)'); r.addColorStop(.3, 'rgba(241,217,138,.6)'); r.addColorStop(1, 'rgba(212,175,55,0)'); g.fillStyle = r; g.fillRect(0, 0, 64, 64); });
    const GLOW = canvasTex(256, 256, g => { const r = g.createRadialGradient(128, 128, 0, 128, 128, 128); r.addColorStop(0, 'rgba(241,217,138,.55)'); r.addColorStop(.35, 'rgba(212,175,55,.18)'); r.addColorStop(1, 'rgba(212,175,55,0)'); g.fillStyle = r; g.fillRect(0, 0, 256, 256); });
    const SHADOW = canvasTex(128, 128, g => { const r = g.createRadialGradient(64, 64, 0, 64, 64, 64); r.addColorStop(0, 'rgba(0,0,0,.85)'); r.addColorStop(1, 'rgba(0,0,0,0)'); g.fillStyle = r; g.fillRect(0, 0, 128, 128); });
    const BEAM = canvasTex(128, 256, (g, w, h) => {
      const gr = g.createLinearGradient(0, 0, 0, h); gr.addColorStop(0, 'rgba(255,236,190,.55)'); gr.addColorStop(1, 'rgba(255,236,190,0)'); g.fillStyle = gr;
      g.beginPath(); g.moveTo(w * .42, 0); g.lineTo(w * .58, 0); g.lineTo(w, h); g.lineTo(0, h); g.closePath(); g.fill();
      const side = g.createLinearGradient(0, 0, w, 0); side.addColorStop(0, 'rgba(0,0,0,1)'); side.addColorStop(.5, 'rgba(0,0,0,0)'); side.addColorStop(1, 'rgba(0,0,0,1)');
      g.globalCompositeOperation = 'destination-out'; g.fillStyle = side; g.fillRect(0, 0, w, h);
    });
    const env = (() => {
      const pm = new T.PMREMGenerator(renderer), s = new T.Scene();
      s.add(new T.Mesh(new T.BoxGeometry(30, 30, 30), new T.MeshBasicMaterial({color: LIGHT ? 0x9c958a : 0x2a2418, side: T.BackSide})));
      const panel = (w, h, color, k, pos) => { const m = new T.Mesh(new T.PlaneGeometry(w, h), new T.MeshBasicMaterial({color: new T.Color(color).multiplyScalar(k), side: T.DoubleSide})); m.position.set(...pos); m.lookAt(0, 0, 0); s.add(m); };
      panel(10, 4, '#fff4dc', 4.0, [0, 12, 3]);     // big warm softbox above
      panel(3, 10, '#f4cd6c', 3.0, [-12, 2, 4]);    // gold strip, left
      panel(3, 10, '#ffffff', 1.8, [12, 3, -2]);    // white strip, right
      panel(14, 2, '#d4af37', 1.4, [0, -8, 8]);     // gold bounce from below
      panel(6, 6, '#fff8ea', 1.2, [0, 2, 14]);      // front fill
