    })();
    const goldMetal = (rough = .22) => new T.MeshStandardMaterial({color: GOLD, metalness: 1, roughness: rough, envMap: env, envMapIntensity: 1.25});
    const loader = new T.TextureLoader(), cache = {};
    const tex = (url, cb, fail) => {
      if (!url) { fail && fail(); return; }
      if (!cache[url]) cache[url] = new Promise((ok, no) => loader.load(url, t => { t.colorSpace = T.SRGBColorSpace; t.anisotropy = 8; ok(t); }, undefined, no));
      cache[url].then(cb, () => fail && fail());
    };
    const dust = (n, box, size, color = LIGHT ? 0xC9A13D : 0xF1D98A, opacity = LIGHT ? .75 : .8) => {
      const pos = new Float32Array(n * 3), sp = new Float32Array(n);
      for (let i = 0; i < n; i++) { pos.set([(Math.random() - .5) * box[0], (Math.random() - .5) * box[1], (Math.random() - .5) * box[2]], i * 3); sp[i] = .2 + Math.random(); }
      const g = new T.BufferGeometry(); g.setAttribute('position', new T.BufferAttribute(pos, 3));
      const p = new T.Points(g, new T.PointsMaterial({size: LIGHT ? size * .8 : size, map: DOT, color, transparent: true, opacity, depthWrite: false, blending: LIGHT ? T.NormalBlending : T.AdditiveBlending}));
      p.userData = {pos, sp, box};
      p.tick = (dt, t) => { for (let i = 0; i < n; i++) { let y = pos[i * 3 + 1] + sp[i] * dt * .25; if (y > box[1] / 2) y = -box[1] / 2; pos[i * 3 + 1] = y; pos[i * 3] += Math.sin(t * .5 + i) * dt * .03; } g.attributes.position.needsUpdate = true; };
      return p;
    };
    // a card in a thin gold frame: photo on the front, the Kiratora back behind
    const framedCard = (img, w) => {
      const h = w * 1.397, g = new T.Group();
      const frame = new T.Mesh(new T.PlaneGeometry(w + .07, h + .07), goldMetal(.3)); frame.position.z = -.002;
      const fm = new T.MeshPhysicalMaterial({map: CARD_BACK, roughness: .32, clearcoat: 1, clearcoatRoughness: .12, envMap: env, envMapIntensity: .55});
      tex(img, t => { fm.map = t; fm.needsUpdate = true; });
      const front = new T.Mesh(new T.PlaneGeometry(w, h), fm); front.position.z = .002;
      const back = new T.Mesh(new T.PlaneGeometry(w, h), new T.MeshPhysicalMaterial({map: CARD_BACK, roughness: .35, clearcoat: 1, envMap: env, envMapIntensity: .6})); back.rotation.y = Math.PI; back.position.z = -.004;
      const frameBack = frame.clone(); frameBack.rotation.y = Math.PI; frameBack.position.z = -.003;
      g.add(frame, frameBack, front, back); g.userData.front = front;
      return g;
    };

    /* ---------- stages: scenes drawn into boxes on the page */
    const stages = [];
    function addStage(el, scene, camera, hooks) {
      const s = Object.assign({el, scene, camera, visible: false, drag: false, lastX: 0, moved: 0, px: 0, py: 0, hover: null, pickables: []}, hooks);
      new IntersectionObserver(es => { s.visible = es[0].isIntersecting; }, {rootMargin: '150px'}).observe(el);
      const ray = new T.Raycaster(), m2 = new T.Vector2();
