      return s;
    }
    const go = u => { if (u) window.location.href = u; };

    /* ===== 1. hero: the box on its pedestal */
    const heroEl = document.querySelector('[data-stage="hero"]');
    if (heroEl && D.box) {
      const sc = new T.Scene(), cam = new T.PerspectiveCamera(30, 1, .1, 100);
      sc.add(new T.AmbientLight(0xfff3dd, LIGHT ? .3 : .55));
      const key = new T.DirectionalLight(0xfff1d6, 2.4); sc.add(key);
      const rim = new T.DirectionalLight(0xF1C75A, 2.6); rim.position.set(4, 3, -6); sc.add(rim);
      const fill = new T.DirectionalLight(0xfff8ee, 1.3); fill.position.set(-3, 1.5, 8); sc.add(fill);
      const BW = 3.0, BH = BW * .944, BD = BW * .534;
      // gold foil: where the photo is gold the box becomes polished metal, so it reflects the light as you turn it
      const foil = (t, gloss) => {
        const img = t.image, w = 256, h = Math.round(256 * img.height / img.width), c = document.createElement('canvas'); c.width = w; c.height = h;
        const g = c.getContext('2d'); g.drawImage(img, 0, 0, w, h);
        const d = g.getImageData(0, 0, w, h), p = d.data;
        for (let i = 0; i < p.length; i += 4) {
          const r = p[i] / 255, gg = p[i + 1] / 255, b = p[i + 2] / 255, mx = Math.max(r, gg, b), mn = Math.min(r, gg, b), l = (mx + mn) / 2, sat = mx === mn ? 0 : (mx - mn) / (1 - Math.abs(2 * l - 1));
          let hue = 0; if (mx !== mn) { hue = mx === r ? ((gg - b) / (mx - mn)) % 6 : mx === gg ? (b - r) / (mx - mn) + 2 : (r - gg) / (mx - mn) + 4; hue *= 60; if (hue < 0) hue += 360; }
          const gold = hue > 34 && hue < 58 && sat > .5 && l > .28 && l < .74 ? 1 : 0;
          p[i] = 255; p[i + 1] = Math.round((gold ? .38 : (l > .8 ? gloss : .62)) * 255); p[i + 2] = gold * 255; p[i + 3] = 255;
        }
        g.putImageData(d, 0, 0);
        const m = new T.CanvasTexture(c); return m;
      };
      const faceMat = (url, gloss) => {
        const m = new T.MeshPhysicalMaterial({color: 0xffffff, roughness: 1, metalness: 1, clearcoat: .35, clearcoatRoughness: .25, envMap: env, envMapIntensity: .9});
        m.metalness = 0; m.roughness = .45;
        tex(url, t => { m.map = t; const orm = foil(t, gloss); m.roughnessMap = orm; m.metalnessMap = orm; m.roughness = 1; m.metalness = 1; m.needsUpdate = true; });
        return m;
      };
      const top = canvasTex(256, 140, (g, w, h) => { g.fillStyle = '#FBF8F0'; g.fillRect(0, 0, w, h); g.strokeStyle = goldGrad(g, 0, 0, w, h); g.lineWidth = 10; g.strokeRect(5, 5, w - 10, h - 10); });
      const side = faceMat(D.box.side, .4), front = faceMat(D.box.front, .34);
      const mats = [side, side, new T.MeshPhysicalMaterial({map: top, roughness: .35, clearcoat: .6, envMap: env, envMapIntensity: .8}), new T.MeshStandardMaterial({color: 0x111111, roughness: .8}), front, front];
      const box = new T.Mesh(new T.BoxGeometry(BW, BH, BD), mats);
      box.userData = {pick: true, url: D.box.url, label: D.box.name + (D.box.price ? ' Â· ' + D.box.price : '')};
      const holder = new T.Group(); holder.add(box); sc.add(holder);
      const pedTop = -BH / 2 - .02;
      const ped = new T.Mesh(new T.CylinderGeometry(2.35, 2.5, .42, 96), new T.MeshPhysicalMaterial({color: LIGHT ? 0xF4F0E8 : 0x0c0c0c, roughness: .16, clearcoat: 1, clearcoatRoughness: .05, envMap: env, envMapIntensity: 1.1}));
      ped.position.y = pedTop - .21; sc.add(ped);
      const ring = new T.Mesh(new T.TorusGeometry(2.36, .03, 16, 180), goldMetal(.18)); ring.rotation.x = Math.PI / 2; ring.position.y = pedTop + .005; sc.add(ring);
      const ring2 = new T.Mesh(new T.TorusGeometry(2.5, .02, 12, 180), goldMetal(.25)); ring2.rotation.x = Math.PI / 2; ring2.position.y = pedTop - .42; sc.add(ring2);
      const shadow = new T.Mesh(new T.PlaneGeometry(BW * 1.5, BD * 2.6), new T.MeshBasicMaterial({map: SHADOW, transparent: true, depthWrite: false, opacity: LIGHT ? .45 : .9})); shadow.rotation.x = -Math.PI / 2; shadow.position.y = pedTop + .012; sc.add(shadow);
      const halo = new T.Sprite(new T.SpriteMaterial({map: GLOW, transparent: true, depthWrite: false, blending: LIGHT ? T.NormalBlending : T.AdditiveBlending, opacity: LIGHT ? .3 : .9})); halo.scale.set(9, 9, 1); halo.position.set(0, .4, -3); sc.add(halo);
      // two soft light beams from above
