      // chase cards in gold frames on a tilted orbit
      const orbit = new T.Group(); sc.add(orbit);
      const cards = (D.ring || []).slice(0, SMALL ? 6 : 8), N = cards.length, R = 4.15;
      cards.forEach((c, i) => {
        const a = (i / N) * Math.PI * 2, g = framedCard(c.img, .92);
        g.position.set(Math.sin(a) * R, 0, Math.cos(a) * R); g.rotation.y = a; g.userData = {pick: true, url: c.url, label: c.name + (c.price ? ' Â· ' + c.price : ''), ph: i * 1.7};
        orbit.add(g);
      });
