          spin += dt * .12; orbit.rotation.y = spin; orbit.rotation.x = .26 + s.py * .12; orbit.position.y = .25;
          orbit.children.forEach(o => { o.position.y = Math.sin(t * .8 + o.userData.ph) * .12; });
          halo.material.opacity = (LIGHT ? .26 : .75) + Math.sin(t * 1.3) * .08;
