    }

    /* ===== 2. the vault: cover-flow of chase cards */
    const vaultEl = document.querySelector('[data-stage="vault"]');
    if (vaultEl && D.vault && D.vault.length >= 3) {
      const sc = new T.Scene(), cam = new T.PerspectiveCamera(32, 1, .1, 100);
      sc.add(new T.AmbientLight(0xffffff, .35));
      const key = new T.DirectionalLight(0xfff1d6, 2.2); key.position.set(-2, 5, 6); sc.add(key);
      const rim = new T.DirectionalLight(0xF1C75A, 1.6); rim.position.set(3, 2, -4); sc.add(rim);
      const items = D.vault, CW = 2.1, CH = CW * 1.397, FLOOR = -CH / 2 - .06;
      const cards = items.map((c, i) => {
        const g = framedCard(c.img, CW); g.userData.pick = true; g.userData.i = i; g.userData.url = c.url;
        // reflection on the black floor
        const rm = new T.MeshBasicMaterial({map: CARD_BACK, transparent: true, opacity: .16, depthWrite: false});
        tex(c.img, t => { rm.map = t; rm.needsUpdate = true; });
        const refl = new T.Mesh(new T.PlaneGeometry(CW, CH), rm); refl.scale.y = -1; refl.position.y = -CH - .12;
        g.add(refl); g.userData.refl = refl;
        sc.add(g); return g;
      });
      // floor fade in front of the reflections, a gold spotlight from above
      const fade = new T.Mesh(new T.PlaneGeometry(40, 6), new T.MeshBasicMaterial({map: canvasTex(4, 128, (g, w, h) => { const gr = g.createLinearGradient(0, 0, 0, h); const fc = LIGHT ? '251,250,247' : '10,10,10'; gr.addColorStop(0, `rgba(${fc},.15)`); gr.addColorStop(.55, `rgba(${fc},.92)`); gr.addColorStop(1, `rgba(${fc},1)`); g.fillStyle = gr; g.fillRect(0, 0, w, h); }), transparent: true, depthWrite: false}));
      fade.position.set(0, FLOOR - 3, 1.6); sc.add(fade);
      const line = new T.Mesh(new T.PlaneGeometry(14, .012), new T.MeshBasicMaterial({color: GOLD, transparent: true, opacity: .55})); line.position.set(0, FLOOR, 1.7); sc.add(line);
      const spot = new T.Mesh(new T.PlaneGeometry(4.6, 9), new T.MeshBasicMaterial({map: BEAM, transparent: true, opacity: .22, depthWrite: false, blending: T.AdditiveBlending})); spot.position.set(0, 2.6, -1.2); spot.visible = !LIGHT; sc.add(spot);
      const glow = new T.Sprite(new T.SpriteMaterial({map: GLOW, transparent: true, depthWrite: false, blending: LIGHT ? T.NormalBlending : T.AdditiveBlending, opacity: LIGHT ? .45 : .7})); glow.scale.set(7, 7, 1); glow.position.set(0, .2, -2.5); sc.add(glow);
      const motes = dust(SMALL ? 80 : 160, [14, 7, 6], .06); sc.add(motes);
      let cur = 0, target = 0, last = performance.now(), hold = false;
      const cap = vaultEl.querySelector('[data-vault-caption]');
      const setCaption = () => {
        const i = ((Math.round(target) % items.length) + items.length) % items.length, c = items[i];
        if (cap) cap.innerHTML = `<span class="vc-set">${esc(c.set || '')}</span><a class="vc-name" href="${esc(c.href)}">${esc(c.name)}</a><span class="vc-price">${esc(c.price)}</span>`;
      };
      const esc = x => String(x).replace(/[&<>"']/g, ch => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[ch]));
      const move = d => { target = Math.round(target) + d; last = performance.now(); setCaption(); };
      vaultEl.querySelector('[data-vault-prev]')?.addEventListener('click', () => move(-1));
      vaultEl.querySelector('[data-vault-next]')?.addEventListener('click', () => move(1));
      vaultEl.addEventListener('keydown', e => { if (e.key === 'ArrowLeft') { move(-1); e.preventDefault(); } if (e.key === 'ArrowRight') { move(1); e.preventDefault(); } });
      vaultEl.addEventListener('mouseenter', () => { hold = true; }); vaultEl.addEventListener('mouseleave', () => { hold = false; last = performance.now(); });
      setCaption();
      const s = addStage(vaultEl, sc, cam, {
        onDrag: dx => { target -= dx / (SMALL ? 120 : 170); },
        onUp: () => { target = Math.round(target); last = performance.now(); setCaption(); },
        onTap: hit => {
          if (!hit) return;
          const n = items.length, ci = ((Math.round(cur) % n) + n) % n;
          if (hit.userData.i === ci) go(hit.userData.url);
          else { let d = hit.userData.i - ci; if (d > n / 2) d -= n; if (d < -n / 2) d += n; move(d); }
        },
        update: (t, dt, w) => {
          const narrow = w < 560;
