          if (!hold && !s.drag && performance.now() - last > 4200) move(1);
          cur += (target - cur) * Math.min(1, dt * 6);
          const n = items.length, gap = narrow ? 1.25 : 1.75, step = narrow ? .55 : .8;
          cards.forEach((g, i) => {
            let d = i - cur; d = ((d % n) + n * 1.5) % n - n / 2;
            const ad = Math.abs(d), sgn = Math.sign(d), k = Math.min(ad, 1);
            g.visible = ad < (narrow ? 3.2 : 5.2);
