            g.userData.refl.material.opacity = .18 - k * .08;
            g.renderOrder = 100 - Math.round(ad * 10);
          });
          spot.material.opacity = .2 + Math.sin(t * .8) * .04;
          motes.tick(dt, t);
        }
      });
      s.pickables = cards;
    }

    /* ===== 3. the Kiratora star in solid gold */
    const starEl = document.querySelector('[data-stage="star"]');
    if (starEl) {
      const sc = new T.Scene(), cam = new T.PerspectiveCamera(30, 1, .1, 100);
      sc.add(new T.AmbientLight(0xffffff, .2));
